# Determine the last approved sent payment request to Robert
import datetime

# Login
venmo_pw=None
for item in apis.supervisor.show_account_passwords():
    if item['account_name']=='venmo':
        venmo_pw=item['password']
        break
access=apis.venmo.login(username='ta.weav@gmail.com', password=venmo_pw)
access_token=access['access_token']

# Fetch all approved sent requests that match query 'Robert'
all_reqs=[]
page_index=0
page_limit=20
while True:
    resp=apis.venmo.show_sent_payment_requests(access_token=access_token, query='Robert', status='approved', page_index=page_index, page_limit=page_limit)
    # Normalize response
    if isinstance(resp, dict) and 'success' in resp:
        data=resp['success']
    else:
        data=resp
    if not data:
        break
    all_reqs.extend(data)
    page_index += 1
    if len(data) < page_limit and page_index>0:
        # likely last page
        pass
    if page_index>50:
        break

# Filter to those whose receiver name starts with 'Robert'
rob_reqs=[]
for r in all_reqs:
    recv=r.get('receiver') or {}
    name=(recv.get('name') or '').strip()
    if name.lower().startswith('robert'):
        rob_reqs.append(r)

# Sort by created_at (fallback approved_at)
def parse_iso(s):
    try:
        return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return datetime.datetime.min

rob_reqs_sorted=sorted(rob_reqs, key=lambda r: parse_iso(r.get('created_at')))
last=rob_reqs_sorted[-1] if rob_reqs_sorted else None

print('total_matching_query_Robert', len(all_reqs))
print('total_receiver_name_startswith_Robert', len(rob_reqs))
print('candidates (sorted by created_at):')
for r in rob_reqs_sorted:
    recv=r.get('receiver') or {}
    print(r.get('payment_request_id'), r.get('amount'), recv.get('name'), recv.get('email'), r.get('created_at'), 'approved_at', r.get('approved_at'))

print('selected_last_payment_request_id', last.get('payment_request_id') if last else None)
if last:
    recv=last['receiver']
    print('selected_receiver_email', recv.get('email'))
    print('selected_amount', last.get('amount'))

